INSERT INTO timeline_events
  (id, location_id, period_label, description, sort_year, sort_order, is_tradition, source_file)
VALUES
  ('tl-muslim-quarter-01', 'muslim-quarter', 'Early Islamic period (from 638 CE)', 'Jerusalem came under Muslim rule; the sacred precinct and the city''s institutions developed through successive Umayyad, Abbasid and Fatimid periods.', 638, 0, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-muslim-quarter-02', 'muslim-quarter', 'Ayyubid period (1187-1250 CE)', 'After Salah al-Din recaptured Jerusalem in 1187, religious and charitable institutions were renewed around the Haram and its approaches.', 1187, 1, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-muslim-quarter-03', 'muslim-quarter', 'Mamluk era (1250-1517 CE)', 'Sultans and governors endowed madrasas, ribats, fountains, markets and residential buildings along the western and northern approaches to Al-Aqsa.', 1250, 2, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-muslim-quarter-04', 'muslim-quarter', '1336-1337 CE', 'The governor Tankiz al-Nasiri completed Souq al-Qattanin, its monumental gate and associated commercial and bath complex.', 1336, 3, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-muslim-quarter-05', 'muslim-quarter', 'Ottoman era (1517-1917 CE)', 'Religious and commercial institutions continued under Ottoman administration, and the quarter remained a centre of Old City life.', 1517, 4, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-muslim-quarter-06', 'muslim-quarter', 'Modern era', 'Homes, schools, worship routes and family businesses continue amid conservation, access and economic pressures.', 1948, 5, FALSE, 'content/ai-ready/muslim-quarter-summary.md'),
  ('tl-christian-quarter-01', 'christian-quarter', '335 CE', 'Constantine''s Church of the Holy Sepulchre was dedicated around the place central to the church''s sacred traditions.', 335, 0, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-christian-quarter-02', 'christian-quarter', '1009 CE', 'The Fatimid caliph al-Hakim ordered major destruction of the church.', 1009, 1, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-christian-quarter-03', 'christian-quarter', '1040s CE', 'A Byzantine-sponsored restoration reopened the sanctuary, although not in its original complete form.', 1040, 2, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-christian-quarter-04', 'christian-quarter', '1149 CE', 'Crusader rebuilding unified key holy places beneath a Romanesque church, dedicated on 15 July 1149.', 1149, 3, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-christian-quarter-05', 'christian-quarter', '1808-1810 CE', 'A destructive fire was followed by substantial restoration, especially around the rotunda and the structure over the tomb.', 1808, 4, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-christian-quarter-06', 'christian-quarter', 'Ottoman era to present', 'Shared use by several churches became governed by the Status Quo; pilgrimage and local commerce continued around the sanctuary.', 1517, 5, FALSE, 'content/ai-ready/christian-quarter-summary.md'),
  ('tl-armenian-quarter-01', 'armenian-quarter', '4th century CE onward', 'Armenian pilgrimage and religious presence in Jerusalem became established after Armenia''s adoption of Christianity.', 350, 0, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-armenian-quarter-02', 'armenian-quarter', '12th century CE', 'Much of the present Cathedral of St James took shape during the Crusader period while preserving earlier traditions and material.', 1150, 1, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-armenian-quarter-03', 'armenian-quarter', '1833 CE', 'The Armenian Patriarchate established a printing press in Jerusalem, an important centre of Armenian-language publishing.', 1833, 2, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-armenian-quarter-04', 'armenian-quarter', '1850s CE', 'A large pilgrim guesthouse was built; the complex later served other community purposes and now houses the Armenian Museum.', 1850, 3, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-armenian-quarter-05', 'armenian-quarter', '1919 CE onward', 'Armenian ceramic artists arriving in Jerusalem helped create the city''s distinctive school of hand-painted tile and pottery.', 1919, 4, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-armenian-quarter-06', 'armenian-quarter', '2022 CE', 'The Edward and Helen Mardigian Museum reopened after major renewal, presenting Armenian Jerusalem and survivor histories.', 2022, 5, FALSE, 'content/ai-ready/armenian-quarter-summary.md'),
  ('tl-maghariba-quarter-01', 'maghariba-quarter', '1187 CE', 'Salah al-Din restored Muslim rule in Jerusalem after the Crusader period.', 1187, 0, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-maghariba-quarter-02', 'maghariba-quarter', '1193 CE', 'Historical accounts associate an Ayyubid charitable endowment with housing Maghrebi pilgrims and residents near the sanctuary.', 1193, 1, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-maghariba-quarter-03', 'maghariba-quarter', 'Mamluk and Ottoman eras', 'Homes, religious institutions and endowed properties formed a compact community beside Bab al-Maghariba and al-Buraq Wall.', 1250, 2, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-maghariba-quarter-04', 'maghariba-quarter', 'British Mandate (1917-1948)', 'Photographs and surveys documented the quarter''s dense stone fabric and North African institutions.', 1917, 3, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-maghariba-quarter-05', 'maghariba-quarter', '10-11 June 1967', 'Most of the quarter was demolished and its residents displaced; sources commonly document roughly 135 structures removed.', 10, 4, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-maghariba-quarter-06', 'maghariba-quarter', 'Present', 'The open plaza differs radically from the former neighbourhood; family memory and archival evidence preserve its history.', 0, 5, FALSE, 'content/ai-ready/maghariba-quarter-summary.md'),
  ('tl-sheikh-jarrah-01', 'sheikh-jarrah', 'Medieval tradition', 'The neighbourhood name became associated with a tomb traditionally attributed to Hussam al-Din al-Jarrahi, a physician linked in tradition to Salah al-Din.', 0, 0, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-sheikh-jarrah-02', 'sheikh-jarrah', 'Late 19th century', 'Prominent Jerusalem families built stone residences north of the Old City as urban life expanded beyond the walls.', 1850, 1, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-sheikh-jarrah-03', 'sheikh-jarrah', '1922 CE', 'The Isaf al-Nashashibi house was built to a design attributed to architect Spiro Khouri, combining local stone architecture with modern villa planning.', 1922, 2, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-sheikh-jarrah-04', 'sheikh-jarrah', 'British Mandate (1917-1948)', 'Villas, consulates, hospitals and institutions reinforced the district''s modern urban character.', 1917, 3, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-sheikh-jarrah-05', 'sheikh-jarrah', '1954-1956 CE', 'Twenty-eight refugee families entered a housing arrangement involving Jordanian authorities and UNRWA; 28 housing units were completed in 1956.', 1954, 4, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-sheikh-jarrah-06', 'sheikh-jarrah', 'Modern era', 'Community life continues amid prolonged legal, property and displacement pressures that require current verification.', 1948, 5, FALSE, 'content/ai-ready/sheikh-jarrah-summary.md'),
  ('tl-silwan-01', 'silwan', 'Ancient periods', 'The spring and valley supported settlement beside Jerusalem''s historic core; water channels and rock-cut systems belong to several phases.', 0, 0, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-silwan-02', 'silwan', '10th century CE', 'Medieval geographer al-Muqaddasi described the spring and the cultivated landscape below Jerusalem.', 950, 1, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-silwan-03', 'silwan', 'Ottoman era (1517-1917 CE)', 'Silwan was an established village whose residents cultivated irrigated gardens and hillside terraces.', 1517, 2, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-silwan-04', 'silwan', '1920 CE', 'Photographs documented the village''s dense stone houses and terraced relationship to the Kidron Valley.', 1920, 3, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-silwan-05', 'silwan', '20th century', 'Population and building expanded across the slopes while farming and spring memories remained part of local identity.', 1950, 4, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-silwan-06', 'silwan', 'Present', 'Archaeology, tourism, homes and community life occupy the same contested landscape and must not be conflated.', 0, 5, FALSE, 'content/ai-ready/silwan-summary.md'),
  ('tl-at-tur-01', 'at-tur', 'Ancient and late antique periods', 'The ridge served as an eastern approach to Jerusalem and a place of burial, worship and cultivation.', 0, 0, FALSE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-at-tur-02', 'at-tur', '4th century CE', 'Christian pilgrimage buildings were established on the Mount of Olives and near Gethsemane in the Byzantine period.', 350, 1, FALSE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-at-tur-03', 'at-tur', 'Crusader period (1099-1187 CE)', 'Churches and pilgrimage routes were rebuilt or reorganised around sites identified in Christian tradition.', 1099, 2, TRUE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-at-tur-04', 'at-tur', 'Ottoman era (1517-1917 CE)', 'The Palestinian village community and multiple religious institutions continued across the ridge.', 1517, 3, FALSE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-at-tur-05', 'at-tur', '1924 CE', 'The present Basilica of the Agony/Church of All Nations at Gethsemane was consecrated; Antonio Barluzzi designed it above earlier remains.', 1924, 4, FALSE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-at-tur-06', 'at-tur', 'Modern era', 'At-Tur developed into a dense Jerusalem neighbourhood while retaining major sacred sites, cemeteries and panoramic viewpoints.', 1948, 5, FALSE, 'content/ai-ready/at-tur-summary.md'),
  ('tl-bab-al-amud-01', 'bab-al-amud', 'Roman era (117-138 CE)', 'A Roman gate complex was built during the reign of Hadrian as the city was refounded as Aelia Capitolina; remains survive below the present entrance, and the Arabic name is believed to recall the column in its plaza.', 117, 0, TRUE, 'content/ai-ready/bab-al-amud-summary.md'),
  ('tl-bab-al-amud-02', 'bab-al-amud', '6th century CE', 'The Madaba mosaic map represented the northern gate, an internal plaza and a column marking the start of the main north-south street.', 550, 1, FALSE, 'content/ai-ready/bab-al-amud-summary.md'),
  ('tl-bab-al-amud-03', 'bab-al-amud', 'Ottoman era (16th century; 1537-1540 CE)', 'The present gate was built as part of the Ottoman walls commissioned by Sultan Suleiman the Magnificent.', 1550, 2, FALSE, 'content/ai-ready/bab-al-amud-summary.md'),
  ('tl-bab-al-amud-04', 'bab-al-amud', '19th-early 20th centuries', 'Photographs documented the gate as a busy arrival point for people, animals and goods from northern routes.', 19, 3, FALSE, 'content/ai-ready/bab-al-amud-summary.md'),
  ('tl-bab-al-amud-05', 'bab-al-amud', 'Mid-20th century', 'Archaeological work exposed parts of the earlier Roman gate beneath the Ottoman structure.', 1950, 4, FALSE, 'content/ai-ready/bab-al-amud-summary.md'),
  ('tl-bab-al-amud-06', 'bab-al-amud', 'Present', 'The steps and square remain a major Palestinian civic gathering place and threshold to Old City markets.', 0, 5, FALSE, 'content/ai-ready/bab-al-amud-summary.md');
INSERT INTO media
  (id, location_id, type, url, thumb_url, width, height, subject, subject_ar, description, description_ar, era, pair_role,
INSERT INTO quiz_questions
  (id, location_id, question, options, answer_index, explanation, source_note, sort_order)
VALUES
  ('quiz-muslim-1', 'muslim-quarter', 'Which Mamluk market forms a monumental approach toward Al-Aqsa?', ARRAY['Souq al-Qattanin', 'Souq al-Bazaar', 'Khan al-Zeit', 'Muristan'], 0, 'Souq al-Qattanin is a vaulted Mamluk market whose eastern gate opens toward the Haram al-Sharif/Al-Aqsa compound.', 'Muslim Quarter §4–5; Museum With No Frontiers, Suq al-Qattanin', 0),
  ('quiz-muslim-2', 'muslim-quarter', 'Under which governor was Souq al-Qattanin completed in 1336–1337?', ARRAY['Salah al-Din', 'Tankiz al-Nasiri', 'Sultan Suleiman', 'Emperor Constantine'], 1, 'The market and associated complex were completed under the Mamluk governor Tankiz al-Nasiri in 737 AH/1336–1337 CE.', 'Muslim Quarter §2 and §5; Museum With No Frontiers', 1),
  ('quiz-muslim-3', 'muslim-quarter', 'Which architectural detail should visitors look for at the Qattanin entrance?', ARRAY['A glass curtain wall', 'Timber pagoda roofs', 'Alternating stone colours and inscription bands', 'A freestanding marble obelisk'], 2, 'The monumental entrance uses coloured stonework, carving and inscription bands typical of prestigious Mamluk portals.', 'Muslim Quarter §5 and §9; Jerusalem Studies, Khan Tankaz', 2),
  ('quiz-muslim-4', 'muslim-quarter', 'Why is the Muslim Quarter described as more than an archaeological district?', ARRAY['It has no historic buildings', 'It is a lived neighbourhood of homes, schools, worship and trade', 'It opens only during festivals', 'It was built entirely after 1948'], 1, 'Its heritage includes continuing residential, educational, religious and commercial life, not monuments alone.', 'Muslim Quarter §1 and §3', 3),
  ('quiz-muslim-5', 'muslim-quarter', 'Which Christian devotional route crosses part of the quarter?', ARRAY['Camino de Santiago', 'Via Dolorosa', 'Appian Way', 'King''s Highway'], 1, 'The Via Dolorosa passes through the quarter, adding a Christian pilgrimage route to its overlapping urban histories.', 'Muslim Quarter §3 and §6', 4),
  ('quiz-christian-1', 'christian-quarter', 'Which arrangement regulates shared responsibilities at the Church of the Holy Sepulchre?', ARRAY['The Status Quo', 'The waqf deed', 'The guild charter', 'The city wall code'], 0, 'Several Christian communities share spaces and responsibilities under the historic Status Quo arrangements.', 'Christian Quarter §3 and §5', 0),
  ('quiz-christian-2', 'christian-quarter', 'In which year was Constantine''s Holy Sepulchre complex dedicated?', ARRAY['638', '1009', '335', '1149'], 2, 'The Constantinian church was dedicated in 335 CE over a site identified in Christian tradition with Calvary and the tomb.', 'Christian Quarter §2; Oxford Reference, Church of the Holy Sepulchre', 1),
  ('quiz-christian-3', 'christian-quarter', 'What major architectural phase was dedicated in 1149?', ARRAY['The Ottoman walls', 'The Crusader rebuilding of the Holy Sepulchre', 'The Armenian printing press', 'The Church of All Nations'], 1, 'Crusader builders unified major sacred spaces into much of the Romanesque church form visible today.', 'Christian Quarter §2; JSAH Crusader reconstruction study', 2),
  ('quiz-christian-4', 'christian-quarter', 'What should visitors notice on the church''s entrance façade?', ARRAY['Two Romanesque portals, one sealed', 'Four minarets', 'An Ottoman clock tower', 'A modern glass dome'], 0, 'The entrance has paired Crusader-period Romanesque portals; one remains sealed while the other is used.', 'Christian Quarter §5 and §9', 3),
  ('quiz-christian-5', 'christian-quarter', 'Why can circulation inside the church change without notice?', ARRAY['The floor is permanently flooded', 'Active services and processions share the building', 'Visitors must follow a fixed museum tour', 'The building closes every afternoon'], 1, 'It is a living, shared place of worship, so ceremonies and processions may temporarily alter visitor movement.', 'Christian Quarter §9 visitor guidance', 4),
  ('quiz-armenian-1', 'armenian-quarter', 'Which craft became a distinctive Armenian contribution to modern Jerusalem?', ARRAY['Hand-painted ceramics', 'Glass blowing', 'Soap making', 'Carpet weaving'], 0, 'Armenian artists arriving from 1919 developed a distinctive Jerusalem school of painted tile and pottery.', 'Armenian Quarter §2 and §5; Tel Aviv University ceramics history', 0),
  ('quiz-armenian-2', 'armenian-quarter', 'When did the Armenian Patriarchate establish its Jerusalem printing press?', ARRAY['1149', '1517', '1833', '1919'], 2, 'The printing press was founded in 1833 and became an important centre of Armenian-language publishing.', 'Armenian Quarter §2 and §5; St James Printing House research', 1),
  ('quiz-armenian-3', 'armenian-quarter', 'Much of the present Cathedral of St James dates to which period?', ARRAY['Twelfth century', 'Fourth century BCE', 'Sixteenth century', 'Twenty-first century'], 0, 'Much of the current cathedral took shape during the twelfth century while preserving earlier traditions and fabric.', 'Armenian Quarter §2 and §5', 2),
  ('quiz-armenian-4', 'armenian-quarter', 'What was the nineteenth-century building now used by the Armenian Museum originally built for?', ARRAY['A railway station', 'A pilgrim guesthouse', 'A military arsenal', 'A cotton market'], 1, 'It was built in the 1850s as a pilgrim guesthouse and later served community and refugee needs before becoming a museum.', 'Armenian Quarter §2; Associated Press museum report', 3),
  ('quiz-armenian-5', 'armenian-quarter', 'Which detail best helps identify the Armenian Quarter in the street?', ARRAY['Blue-and-white ceramic plaques and Armenian script', 'Neon skyscraper signs', 'Roman milestone columns only', 'Wooden suspension bridges'], 0, 'Armenian inscriptions, carved cross-stones and hand-painted ceramic plaques mark the community landscape.', 'Armenian Quarter §9', 4),
  ('quiz-maghariba-1', 'maghariba-quarter', 'With which wider region was the historic Maghariba Quarter connected?', ARRAY['The Maghreb', 'The Balkans', 'Anatolia', 'Mesopotamia'], 0, 'The quarter served communities and pilgrims connected with North Africa and the wider Maghreb.', 'Maghariba Quarter §1 and §3; Jerusalem Story', 0),
  ('quiz-maghariba-2', 'maghariba-quarter', 'Which year is associated with the Ayyubid endowment for Maghrebi residents and pilgrims?', ARRAY['1099', '1193', '1537', '1922'], 1, 'Historical accounts associate the charitable endowment with 1193 CE, soon after Salah al-Din restored Muslim rule.', 'Maghariba Quarter §2; PASSIA waqf study', 1),
  ('quiz-maghariba-3', 'maghariba-quarter', 'What happened to most of the quarter on 10–11 June 1967?', ARRAY['It became a museum', 'It was demolished and residents were displaced', 'It was enclosed by a new medieval wall', 'It was moved outside the Old City'], 1, 'Most of the built fabric was demolished and residents were displaced, leaving a radically changed urban setting.', 'Maghariba Quarter §2 and §5; UNESCO and PASSIA documentation', 2),
  ('quiz-maghariba-4', 'maghariba-quarter', 'What is essential for understanding the neighbourhood that no longer survives intact?', ARRAY['Only current satellite images', 'Historic photographs, waqf records and testimony', 'Legends without dates', 'A modern shopping map'], 1, 'Archival images, records and attributed family testimony help reconstruct the erased lanes and social fabric.', 'Maghariba Quarter §5, §7 and §9', 3),
  ('quiz-maghariba-5', 'maghariba-quarter', 'Which visitor method best reads this site responsibly?', ARRAY['Assume the present plaza is unchanged since antiquity', 'Compare the current space with a dated historical view', 'Ignore the surviving ascent', 'Photograph worshippers without asking'], 1, 'A dated comparison reveals the sharp change in scale and prevents the modern plaza from being mistaken for an unchanged ancient space.', 'Maghariba Quarter §9 visitor walkthrough', 4),
  ('quiz-sheikh-1', 'sheikh-jarrah', 'When did prominent Jerusalem families expand housing in Sheikh Jarrah outside the walls?', ARRAY['Late Ottoman era', 'Umayyad era', 'Crusader era', 'Early Byzantine era'], 0, 'Prominent Palestinian families built residences there during Jerusalem''s late nineteenth-century expansion.', 'Sheikh Jarrah §2', 0),
  ('quiz-sheikh-2', 'sheikh-jarrah', 'When was the Isaf al-Nashashibi house completed?', ARRAY['1833', '1922', '1956', '2001'], 1, 'The house was completed in 1922 and its design is attributed to architect Spiro Khouri.', 'Sheikh Jarrah §2 and §5; Jerusalem Quarterly', 1),
  ('quiz-sheikh-3', 'sheikh-jarrah', 'How many housing units do UN records note as completed in 1956?', ARRAY['12', '28', '54', '135'], 1, 'UN documentation records completion of 28 units connected with an arrangement for 28 refugee families.', 'Sheikh Jarrah §2 and §5; United Nations records', 2),
  ('quiz-sheikh-4', 'sheikh-jarrah', 'Which features express the neighbourhood''s villa heritage?', ARRAY['Stone arches, deep windows, tiled roofs and gardens', 'Glass towers and steel bridges', 'Mud-brick pyramids', 'Only underground rooms'], 0, 'Late Ottoman and Mandate-era villas use Jerusalem stone, arched openings, verandas, tiled roofs and planted gardens.', 'Sheikh Jarrah §9', 3),
  ('quiz-sheikh-5', 'sheikh-jarrah', 'Why must current property cases not be answered from the static heritage summary?', ARRAY['They are fictional', 'Legal outcomes and conditions can change', 'The neighbourhood has no residents', 'Historic architecture settles ownership'], 1, 'Current legal facts are time-sensitive and require up-to-date authoritative sources; architectural history cannot determine them.', 'Sheikh Jarrah §5 and §8 fact-guard note', 4),
  ('quiz-silwan-1', 'silwan', 'Which feature is central to Silwan''s historic landscape?', ARRAY['Ain Silwan', 'Bab al-Amud', 'Souq al-Qattanin', 'St James Cathedral'], 0, 'Ain Silwan connects water, settlement, cultivation and the neighbourhood''s living heritage.', 'Silwan §1 and §3', 0),
  ('quiz-silwan-2', 'silwan', 'Which medieval geographer described the spring and cultivated landscape below Jerusalem?', ARRAY['Herodotus', 'Al-Muqaddasi', 'Ibn Battuta', 'Marco Polo'], 1, 'The tenth-century geographer al-Muqaddasi described Jerusalem''s water and cultivated landscape.', 'Silwan §2; scholarly editions of al-Muqaddasi', 1),
  ('quiz-silwan-3', 'silwan', 'What do Silwan''s retaining walls and stacked roofs help visitors understand?', ARRAY['Its steep vertical terrain', 'A flat Roman parade ground', 'A coastal harbour', 'A planned industrial grid'], 0, 'Homes, paths and terraces respond to a steep valley-side landscape that is best read vertically.', 'Silwan §5 and §9', 2),
  ('quiz-silwan-4', 'silwan', 'Why should archaeology and present community life not be conflated?', ARRAY['Only one of them is real', 'They are different evidence layers sharing the same landscape', 'They occur in different countries', 'Archaeology has no dates'], 1, 'Ancient remains and contemporary Palestinian life overlap spatially but answer different historical and social questions.', 'Silwan §2, §5 and §8', 3),
  ('quiz-silwan-5', 'silwan', 'Which practical advice fits Silwan''s terrain?', ARRAY['Wear shoes with grip and avoid unmarked shortcuts', 'Expect level indoor corridors', 'Visit only by boat', 'Ignore current access conditions'], 0, 'The slopes and paths can be steep and uneven, so stable footwear and locally verified routes are important.', 'Silwan §9 visitor guidance', 4),
  ('quiz-tur-1', 'at-tur', 'What can the Mount of Olives viewpoint help visitors read?', ARRAY['The relation of walls, valleys and eastern ridge', 'The Mediterranean coastline', 'A coastal railway terminal', 'A modern airport runway'], 0, 'The panorama shows the physical relationship among the Old City walls, Kidron Valley and eastern ridge.', 'At-Tur §1 and §5', 0),
  ('quiz-tur-2', 'at-tur', 'Which valley separates the Mount of Olives from the Old City?', ARRAY['Jezreel Valley', 'Kidron Valley', 'Ayalon Valley', 'Jordan Valley'], 1, 'The Kidron Valley lies between the eastern Old City wall and the Mount of Olives ridge.', 'At-Tur §5; Custody of the Holy Land', 1),
  ('quiz-tur-3', 'at-tur', 'When was the present Church of All Nations consecrated?', ARRAY['1149', '1517', '1924', '1981'], 2, 'The present church at Gethsemane, designed by Antonio Barluzzi above earlier remains, was consecrated in 1924.', 'At-Tur §2 and §5; Custody of the Holy Land', 2),
  ('quiz-tur-4', 'at-tur', 'What creates the church''s solemn visual atmosphere?', ARRAY['A bright glass office interior', 'Dark blue vaults and subdued light', 'A rotating neon sign', 'An uncovered concrete roof'], 1, 'Its dark blue vaulting and controlled light contrast with the bright valley outside and support a devotional atmosphere.', 'At-Tur §5 and §9', 3),
  ('quiz-tur-5', 'at-tur', 'Which statement best respects the ridge''s identity?', ARRAY['It is only a pilgrimage viewpoint', 'It is both a sacred landscape and a living Palestinian neighbourhood', 'It contains no modern institutions', 'All tomb identifications are archaeologically certain'], 1, 'Homes, schools, hospitals and local commerce coexist with shrines, cemeteries and viewpoints.', 'At-Tur §1, §3 and §7', 4),
  ('quiz-amud-1', 'bab-al-amud', 'The visible monumental façade of Bab al-Amud belongs mainly to which period?', ARRAY['Ottoman', 'Roman', 'Byzantine', 'Mamluk'], 0, 'The present façade was built in 1537–1540 as part of Sultan Suleiman''s Ottoman walls, above earlier remains.', 'Bab al-Amud §2 and §5; Jerusalem Foundation', 0),
  ('quiz-amud-2', 'bab-al-amud', 'What is the likely origin of the Arabic name Bab al-Amud, “Gate of the Column”?', ARRAY['A modern lamp post', 'A column shown in the Roman plaza', 'A Mamluk minaret', 'A Crusader drawbridge'], 1, 'The sixth-century Madaba map shows a column in the inner Roman plaza, remembered in the Arabic name.', 'Bab al-Amud §2 and §3; University of Michigan gate record', 1),
  ('quiz-amud-3', 'bab-al-amud', 'During whose reign was the earlier Roman gate complex built?', ARRAY['Hadrian', 'Constantine', 'Salah al-Din', 'Suleiman'], 0, 'The Roman gate complex dates to the reign of Hadrian, when the city was refounded as Aelia Capitolina.', 'Bab al-Amud §2; University of Michigan gate record', 2),
  ('quiz-amud-4', 'bab-al-amud', 'Why does the gate passage turn instead of running straight through?', ARRAY['To create a defensive bent entrance', 'To follow an underground river', 'To make room for a railway', 'To face the Mediterranean'], 0, 'The bent-axis passage controls movement and prevents a direct approach through the fortification.', 'Bab al-Amud §5 and §9', 3),
  ('quiz-amud-5', 'bab-al-amud', 'Which market route continues south after entering the gate?', ARRAY['Souq al-Qattanin', 'Khan al-Zeit', 'Souq al-Bazaar', 'Karm al-Mufti'], 1, 'Khan al-Zeit carries the route into the Old City through a roofed commercial street.', 'Bab al-Amud §1, §4 and §9', 4);
